async function setupTsciProject(directory = process.cwd(), devDependencies = ["@types/react", "tscircuit"]) {
  const projectPath = path23.resolve(directory);
  if (!fs20.existsSync(projectPath)) {
    fs20.mkdirSync(projectPath, { recursive: true });
  }
  const packageManager = getPackageManager();
  console.log(`Initializing project in ${projectPath}...`);
  process.chdir(projectPath);
  if (!fs20.existsSync("package.json")) {
    try {
      packageManager.init({ cwd: projectPath });
      console.log("Project initialized successfully.");
    } catch (error) {
      console.warn("Failed to automatically initialize project.");
      const initCommand = packageManager.getInitCommand();
      console.warn("Please initialize using the command:");
      console.warn(`  ${initCommand}`);
    }
  }
  const packageJsonPath = path23.join(projectPath, "package.json");
  const packageJson = JSON.parse(fs20.readFileSync(packageJsonPath, "utf-8"));
  packageJson.scripts = {
    ...packageJson.scripts || {},
    dev: "tsci dev",
    start: "tsci dev"
  };
  fs20.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
  if (devDependencies.length > 0) {
    console.log("Installing dependencies...");
    try {
      await packageManager.installDeps({
        deps: devDependencies,
        cwd: projectPath,
        dev: true
      });
      console.log("Dependencies installed successfully.");
    } catch (error) {
      console.warn("Failed to automatically install the required dependencies.");
      const installCommand = packageManager.getInstallDepsCommand(devDependencies, true);
      console.warn("Please install them manually using the command:");
      console.warn(`  ${installCommand}`);
    }
  }
  return packageJson.name || "unknown";
}

